begin;
create temp table ids(name text primary key,id uuid default gen_random_uuid());
insert into ids(name) values('owner'),('other'),('viewer'),('company'),('elsewhere'),('batch'),('batch2'),('request');
grant select,insert,update on ids to authenticated,service_role;
create function pg_temp.id(text) returns uuid language sql as $$select id from ids where name=$1$$;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin
 if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text) returns void language plpgsql as $$begin
 begin execute statement;exception when others then insert into results values(name,true);return;end;
 raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select id,id::text||'@queue-test.invalid',now(),'authenticated','authenticated' from ids where name in ('owner','viewer','other');
insert into public.companies(id,name) values(pg_temp.id('company'),'Queue test'),(pg_temp.id('elsewhere'),'Queue other');
insert into public.company_members values(pg_temp.id('company'),pg_temp.id('owner'),'owner',now()),(pg_temp.id('company'),pg_temp.id('viewer'),'viewer',now()),(pg_temp.id('elsewhere'),pg_temp.id('other'),'owner',now());
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('owner'),'role','authenticated')::text,true);
set local role authenticated;
update ids set id=public.begin_resume_batch_files(pg_temp.id('company'),'email','[{"name":"a.pdf"},{"name":"b.pdf"},{"name":"c.pdf"},{"name":"d.pdf"},{"name":"not-sent.pdf"}]') where name='batch';
select pg_temp.ok('manifest persists all filenames before receiving bytes',(select count(*)=5 from public.resume_batch_entries where batch_id=pg_temp.id('batch')));
select pg_temp.denied('user cannot claim jobs','select public.claim_resume_jobs()');
select pg_temp.denied('user cannot forge queue states','update public.resume_jobs set state=''succeeded''');
select pg_temp.denied('user cannot inspect dispatcher token','select * from private.resume_dispatch');
select pg_temp.denied('user cannot call dispatcher','select private.dispatch_resume_queue()');
reset role;
insert into public.resume_batches(id,company_id,uploaded_by,source,file_count) values(pg_temp.id('batch2'),pg_temp.id('elsewhere'),pg_temp.id('other'),'email',2);
create function pg_temp.accept(actor uuid,company uuid,batch uuid,slot integer) returns void language plpgsql as $$declare r jsonb;begin
 r:=public.reserve_resume(actor,company,batch,slot,repeat((slot+1)::text,64),'fixture.pdf','application/pdf',10,1);
 perform public.finish_resume_upload(actor,company,(r->>'documentId')::uuid,(r->>'token')::uuid);
end$$;
set local role service_role;
select pg_temp.accept(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),n) from generate_series(0,3) n;
select pg_temp.accept(pg_temp.id('other'),pg_temp.id('elsewhere'),pg_temp.id('batch2'),n) from generate_series(0,1) n;
select pg_temp.ok('accepted files automatically create durable jobs',(select count(*)=6 from public.resume_jobs where company_id in (pg_temp.id('company'),pg_temp.id('elsewhere'))));
select pg_temp.ok('receipt updates manifest atomically',(select count(*)=4 from public.resume_batch_entries where batch_id=pg_temp.id('batch') and state='received'));
reset role;
create temp table claimed as select * from public.claim_resume_jobs();
grant select on claimed to authenticated,service_role;
select pg_temp.ok('dispatcher claims at most two jobs',(select count(*)=2 from claimed));
select pg_temp.ok('leases have bounded expiry',(select bool_and(lease_until=now()+interval '4 minutes' and attempts=1) from claimed));
select count(*) from public.claim_resume_jobs();
select pg_temp.ok('another company progresses independently',(select count(*)=4 from public.resume_jobs where state='running' and company_id in (pg_temp.id('company'),pg_temp.id('elsewhere'))));
select pg_temp.ok('company concurrency cannot exceed two',(select max(n)=2 from (select count(*) n from public.resume_jobs where state='running' group by company_id)s));
select pg_temp.ok('repeated claim does not double process',(select count(*)=0 from public.claim_resume_jobs()));
insert into ids(name,id) select 'running',id from public.resume_jobs where company_id=pg_temp.id('company') and state='running' limit 1;
insert into ids(name,id) select 'running2',id from public.resume_jobs where company_id=pg_temp.id('company') and state='running' and id<>pg_temp.id('running') limit 1;
insert into ids(name,id) select 'pending',id from public.resume_jobs where company_id=pg_temp.id('company') and state='queued' limit 1;
insert into ids(name,id) select 'candidate',candidate_id from public.resume_jobs where id=pg_temp.id('running');
insert into ids(name,id) select 'token',lease_token from public.resume_jobs where id=pg_temp.id('running');
set local role authenticated;
select pg_temp.ok('active reprocess reuses existing job',public.request_resume_job(pg_temp.id('company'),pg_temp.id('candidate'),'reprocess',pg_temp.id('request'))=pg_temp.id('running'));
select pg_temp.denied('running work cannot be cancelled',$q$select public.control_resume_job(pg_temp.id('company'),pg_temp.id('running'),'cancel')$q$);
select public.control_resume_job(pg_temp.id('company'),pg_temp.id('pending'),'cancel');
select pg_temp.ok('queued work can be cancelled',(select state='cancelled' from public.resume_jobs where id=pg_temp.id('pending')));
reset role;
select pg_temp.ok('wrong lease token cannot persist',not public.settle_resume_job(pg_temp.id('running'),gen_random_uuid(),'succeeded','{}'));
select public.settle_resume_job(pg_temp.id('running'),pg_temp.id('token'),'error','{}','transient','Temporary test failure');
select pg_temp.ok('first transient failure backs off one minute',(select state='retry_wait' and available_at=now()+interval '1 minute' and lease_token is null from public.resume_jobs where id=pg_temp.id('running')));
select public.settle_resume_job(id,lease_token,'succeeded','{"nome_completo":"Synthetic success","confianca":0.9}') from public.resume_jobs where id=pg_temp.id('running2');
select pg_temp.ok('success updates document and candidate',(select d.state='completed' and c.processing_status='concluido' from public.resume_jobs j join public.resume_documents d on d.id=j.document_id join public.candidates c on c.id=j.candidate_id where j.id=pg_temp.id('running2')));
select pg_temp.ok('completed token cannot save twice',not public.settle_resume_job(pg_temp.id('running'),pg_temp.id('token'),'succeeded','{}'));
-- Hold remaining initial work to focus on retry timing.
update public.resume_jobs set available_at=now()+interval '1 day' where state='queued';
update public.resume_jobs set available_at=now() where id=pg_temp.id('running');
select count(*) from public.claim_resume_jobs();
select public.settle_resume_job(id,lease_token,'error','{}','transient','Again') from public.resume_jobs where id=pg_temp.id('running');
select pg_temp.ok('second failure backs off five minutes',(select attempts=2 and state='retry_wait' and available_at=now()+interval '5 minutes' from public.resume_jobs where id=pg_temp.id('running')));
update public.resume_jobs set available_at=now() where id=pg_temp.id('running');
select count(*) from public.claim_resume_jobs();
select public.settle_resume_job(id,lease_token,'error','{}','transient','Exhausted') from public.resume_jobs where id=pg_temp.id('running');
select pg_temp.ok('three failed attempts stop automatic retries',(select attempts=3 and state='failed' from public.resume_jobs where id=pg_temp.id('running')));
set local role authenticated;
select pg_temp.ok('batch retry selects only failed jobs',public.control_resume_batch(pg_temp.id('company'),pg_temp.id('batch'),'retry')=1);
select pg_temp.ok('successful jobs never retried by batch',(select count(*)=1 from public.resume_jobs where candidate_id=(select candidate_id from public.resume_jobs where id=pg_temp.id('running2'))));
select pg_temp.ok('new attempt cycle is visible in history',(select max(generation)=2 from public.resume_jobs where candidate_id=pg_temp.id('candidate')));
select public.control_resume_batch(pg_temp.id('company'),pg_temp.id('batch'),'cancel');
select pg_temp.ok('batch cancellation retains unsent manifest',(select state='cancelled' from public.resume_batch_entries where batch_id=pg_temp.id('batch') and slot=4));
reset role;
select pg_temp.denied('cancelled manifest rejects late upload',$q$select pg_temp.accept(pg_temp.id('owner'),pg_temp.id('company'),pg_temp.id('batch'),4)$q$);
-- Recovery: expire one live lease from the other company, then fence its old token.
insert into ids(name,id) select 'interrupted',id from public.resume_jobs where company_id=pg_temp.id('elsewhere') and state='running' limit 1;
insert into ids(name,id) select 'expiredtoken',lease_token from public.resume_jobs where id=pg_temp.id('interrupted');
update public.resume_jobs set lease_until=now()-interval '1 second' where id=pg_temp.id('interrupted');
select count(*) from public.claim_resume_jobs();
select pg_temp.ok('crashed worker recovered after lease expires',(select state='retry_wait' and error_kind='interrupted' from public.resume_jobs where id=pg_temp.id('interrupted')));
select pg_temp.ok('expired worker cannot overwrite recovery',not public.settle_resume_job(pg_temp.id('interrupted'),pg_temp.id('expiredtoken'),'succeeded','{}'));
update public.resume_jobs set available_at=now() where id=pg_temp.id('interrupted');
select count(*) from public.claim_resume_jobs();
select pg_temp.ok('recovered work receives a fresh lease',(select state='running' and attempts=2 and lease_token<>pg_temp.id('expiredtoken') from public.resume_jobs where id=pg_temp.id('interrupted')));
delete from public.company_members where user_id=pg_temp.id('other');
select public.settle_resume_job(id,lease_token,'succeeded','{"nome_completo":"must not save"}') from public.resume_jobs where id=pg_temp.id('interrupted');
select pg_temp.ok('revoked actor cannot save AI result',(select j.state='cancelled' and c.nome is distinct from 'must not save' from public.resume_jobs j join public.candidates c on c.id=j.candidate_id where j.id=pg_temp.id('interrupted')));
select pg_temp.ok('revocation clears stale processing status',(select c.processing_status='erro' from public.resume_jobs j join public.candidates c on c.id=j.candidate_id where j.id=pg_temp.id('interrupted')));
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('viewer'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.ok('viewer can inspect company progress',(select count(*)>0 from public.resume_jobs));
select pg_temp.denied('viewer cannot retry',$q$select public.request_resume_job(pg_temp.id('company'),pg_temp.id('candidate'),'reprocess',gen_random_uuid())$q$);
select pg_temp.denied('cross-company job control rejected',$q$select public.control_resume_job(pg_temp.id('elsewhere'),pg_temp.id('interrupted'),'retry')$q$);
reset role;
select set_config('request.jwt.claims',json_build_object('sub',pg_temp.id('other'),'role','authenticated')::text,true);
set local role authenticated;
select pg_temp.ok('revoked member sees no job history',(select count(*)=0 from public.resume_jobs));
select pg_temp.ok('revoked member sees no attempts',(select count(*)=0 from public.resume_job_attempts));
select pg_temp.ok('revoked member sees no batch manifests',(select count(*)=0 from public.resume_batch_entries));
reset role;
select json_build_object('passed',count(*),'failed',0,'tests',json_agg(name)) as results from results;
rollback;
